+        </Field>
+        <Field>
+          <FieldLabel htmlFor={`${prefix}-member-id`}>Payer member identifier</FieldLabel>
+          <Input
+            id={`${prefix}-member-id`}
+            value={value.memberId ?? ''}
+            disabled={disabled}
+            autoComplete="off"
+            className="min-h-11"
+            onChange={(event) => onChange({ memberId: nullable(event.currentTarget.value) })}
