+    api.create.mockResolvedValue({
+      commandId: COMMAND_ID,
+      action: 'create',
+      caseId: CASE_ID,
+      committedAt: '2026-09-17T12:00:00Z',
+    });
+    const { result, rerender } = renderHook(
+      ({ projected }) => useCaseCommand(CASE_ID, projected),
