+    expect(result.current.outcome).toBe('refused');
+    expect(result.current.pending).toBe(false);
+    expect(result.current.message).toContain('permission');
+  });
+});
diff --git a/web/src/features/case-queue/hooks/use-case-command.ts b/web/src/features/case-queue/hooks/use-case-command.ts
